    seen = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] == 2 and not seen[yy][xx]):
                        seen[yy][xx] = True
                        stack.append((yy, xx))
            components.append(cells)

    components.sort(key=lambda cells: min(c for r, c in cells))
    color = 8 if len(components) % 2 == 1 else 2
    out = [row[:] for row in grid]

    for cells in components:
        if color == 8:
            for r, c in cells:
                out[r][c] = 8
        color = 10 - color  # alternate 8 and 2

    return out
